43	/// Assert that `node->children` has at least `child_num` elements
44	static void checkChildrenSize(QueryPlan::Node * node, size_t child_num)
45	{
46	    auto & child = node->step;
47	    if (child_num > child->getInputHeaders().size() || child_num > node->children.size())
48	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Wrong number of children: expected at least {}, got {} children and {} streams",
49	                        child_num, child->getInputHeaders().size(), node->children.size());
50	}
