214	FiltersForTableExpressionMap collectFiltersForAnalysis(const QueryTreeNodePtr & query_tree, const QueryTreeNodes & table_nodes, const ContextPtr & query_context, const ActionsDAG * post_filter)
215	{
216	    bool collect_filters = false;
217	    const auto & settings = query_context->getSettingsRef();
218	
219	    bool parallel_replicas_estimation_enabled
220	        = query_context->canUseParallelReplicasOnInitiator() && settings[Setting::parallel_replicas_min_number_of_rows_per_replica] > 0;
221	
222	    for (const auto & table_expression : table_nodes)
223	    {
224	        auto * table_node = table_expression->as<TableNode>();
225	        auto * table_function_node = table_expression->as<TableFunctionNode>();
226	        if (!table_node && !table_function_node)
227	            continue;
228	
229	        const auto & storage = table_node ? table_node->getStorage() : table_function_node->getStorage();
230	        if (typeid_cast<const StorageDistributed *>(storage.get())
231	            || (parallel_replicas_estimation_enabled && std::dynamic_pointer_cast<MergeTreeData>(storage)))
232	        {
233	            collect_filters = true;
234	            break;
235	        }
236	        if (typeid_cast<const StorageObjectStorageCluster *>(storage.get()))
237	        {
238	            collect_filters = true;
239	            break;
240	        }
241	        if (typeid_cast<const StorageView *>(storage.get()))
242	        {
243	            collect_filters = true;
244	            break;
245	        }
246	    }
247	
248	    if (!collect_filters)
249	        return {};
250	
251	    ResultReplacementMap replacement_map;
252	
253	    auto updated_query_tree = replaceTableExpressionsWithDummyTables(query_tree, table_nodes, query_context, &replacement_map);
254	    /// disable parallel replicas to collect filters
255	    {
256	        if (auto * query_node = updated_query_tree->as<QueryNode>())
257	        {
258	            auto new_context = Context::createCopy(query_node->getMutableContext());
259	            new_context->setSetting("enable_parallel_replicas", false);
260	            query_node->getMutableContext() = new_context;
261	        }
262	        else if (auto * union_node = updated_query_tree->as<UnionNode>())
263	        {
264	            auto new_context = Context::createCopy(union_node->getMutableContext());
265	            new_context->setSetting("enable_parallel_replicas", false);
266	            union_node->getMutableContext() = new_context;
267	        }
268	    }
269	
270	    std::unordered_map<const IStorage *, QueryTreeNodePtr> dummy_storage_to_table;
271	
272	    for (auto & [from_table_expression, dummy_table_expression] : replacement_map)
273	    {
274	        auto * dummy_storage = dummy_table_expression->as<TableNode &>().getStorage().get();
275	        dummy_storage_to_table.emplace(dummy_storage, from_table_expression);
276	    }
277	
278	    SelectQueryOptions select_query_options;
279	    Planner planner(updated_query_tree, select_query_options);
280	    planner.buildQueryPlanIfNeeded();
281	
282	    auto & result_query_plan = planner.getQueryPlan();
283	
284	    /// This part is needed to support "skip unused shards" for the View over Distributed.
285	    /// When reading through a View, the outer WHERE clause is not visible to the inner query.
286	    /// Inject it as a FilterStep on top of the dummy plan so that predicate-push-down works.
287	    if (post_filter)
288	    {
289	        const auto & header = *result_query_plan.getCurrentHeader();
290	        bool all_inputs_present = true;
291	        for (const auto & input : post_filter->getInputs())
292	        {
293	            if (!header.has(input->result_name))
294	            {
295	                all_inputs_present = false;
296	                break;
297	            }
298	        }
299	
300	        if (all_inputs_present)
301	        {
302	            auto filter_dag = post_filter->clone();
303	            // filter_dag.appendInputsForUnusedColumns(header);
304	            String filter_column_name = filter_dag.getOutputs().at(0)->result_name;
305	            auto filter_step = std::make_unique<FilterStep>(
306	                result_query_plan.getCurrentHeader(),
307	                std::move(filter_dag),
308	                filter_column_name,
309	                true /* remove_filter_column */);
310	            result_query_plan.addStep(std::move(filter_step));
311	        }
312	    }
313	
314	    QueryPlanOptimizationSettings optimization_settings(query_context);
315	    optimization_settings.build_sets = false; // no need to build sets to collect filters
316	    optimization_settings.materialize_ctes = false; // no need to materialize CTEs to collect filters
317	    result_query_plan.optimize(optimization_settings);
318	
319	    FiltersForTableExpressionMap res;
320	
321	    std::vector<QueryPlan::Node *> nodes_to_process;
322	    nodes_to_process.push_back(result_query_plan.getRootNode());
323	
324	    while (!nodes_to_process.empty())
325	    {
326	        const auto * node_to_process = nodes_to_process.back();
327	        nodes_to_process.pop_back();
328	        nodes_to_process.insert(nodes_to_process.end(), node_to_process->children.begin(), node_to_process->children.end());
329	
330	        auto * read_from_dummy = typeid_cast<ReadFromDummy *>(node_to_process->step.get());
331	        if (!read_from_dummy)
332	            continue;
333	
334	        if (auto filter_actions = read_from_dummy->detachFilterActionsDAG())
335	        {
336	            const auto & table_node = dummy_storage_to_table.at(&read_from_dummy->getStorage());
337	            res[table_node] = FiltersForTableExpression{filter_actions, read_from_dummy->getPrewhereInfo()};
338	        }
339	    }
340	
341	    return res;
342	}
