344	FiltersForTableExpressionMap collectFiltersForAnalysis(const QueryTreeNodePtr & query_tree_node, const SelectQueryOptions & select_query_options, const ActionsDAG * post_filter)
345	{
346	    if (select_query_options.only_analyze)
347	        return {};
348	
349	    auto * query_node = query_tree_node->as<QueryNode>();
350	    auto * union_node = query_tree_node->as<UnionNode>();
351	
352	    if (!query_node && !union_node)
353	        throw Exception(ErrorCodes::UNSUPPORTED_METHOD,
354	            "Expected QUERY or UNION node. Actual {}",
355	            query_tree_node->formatASTForErrorMessage());
356	
357	    auto context = query_node ? query_node->getContext() : union_node->getContext();
358	
359	    auto table_expressions_nodes
360	        = extractTableExpressions(query_tree_node, false /* add_array_join */, true /* recursive */);
361	
362	    return collectFiltersForAnalysis(query_tree_node, table_expressions_nodes, context, post_filter);
363	}

